#include <bits/stdc++.h>
using namespace std;

int main() {
    long long n;
    cin >> n;

    long long tmp = n;
    vector<pair<long long, int>> d;
    for (long long p = 2; p * p <= tmp; ++p) {
        if (tmp % p == 0) {
            int cnt = 0;
            while (tmp % p == 0) {
                tmp /= p;
                ++cnt;
            }
            d.push_back({p, cnt});
        }
    }
    if (tmp > 1) {
        d.push_back({tmp, 1});
    }

    if (d.size() == 1) {
        cout << d[0].first << endl;
    } else {
        cout << 1 << endl;
    }

    return 0;
}

